def poly_iterate(p, n):
    result = [0, 1]  # X
    for _ in range(n):
        result = poly_compose(p, result)
    return result

def conjugacy_invert(y, n, h, h_inv, g_inv):
    z = h(y)
    for _ in range(n):
        z = g_inv(z)
    return h_inv(z)

def brute_invert(p, c, n, solve):
    pre = [c]
    for _ in range(n):
        pre = [x for y in pre for x in solve(p, y)]
    return pre
